try{await openDB(demoMode?'delivery-manager-demo':'delivery-manager');state=await read();if(demoMode&&!state.demoSeedVersion){state=createDemoData();await save(state);}if(demoMode&&ensureDemoCurrentShift(state)){await save(state);}if(demoMode&&ensureDemoAnalytics(state))await save(state);if(applySettingsDefaults(state))await save(state);reconcileDispatchColors(state);applyBatchPriorities(state);completeRuns(state);await save(state);render();loadLocations().then(()=>{if(state&&!settingsEditing)render();}).catch(()=>{});if(!demoMode){const reconcile=()=>syncNotifications(state).catch(()=>{});reconcile();syncOilEmail(state).catch(()=>{});addEventListener('online',()=>{reconcile();syncOilEmail(state).then(()=>{if(tab==='settings'&&!$('#modal').open)render();}).catch(()=>{});});navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='open-run'){renderReturnGate();return;}if(e.data?.type==='open-eos'){if($('#modal').open)return notify('Close this form when ready to review your shift.');tab='shift';render();checkShiftReminder();}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)reconcile();});setInterval(reconcile,60000);}setInterval(checkShiftReminder,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkShiftReminder();});setTimeout(()=>{if(!$('#modal').open)checkAlcoholReceiptJar();checkShiftReminder();},1000);registerUpdates().catch(()=>{});}catch(e){$('#app').innerHTML='<main class="main"><h1>We couldn’t open your records.</h1><p>Local storage may be unavailable. Please reopen this app in a regular browser window. No records have been reset.</p></main>';}
window.addEventListener('online',()=>state&&render());window.addEventListener('offline',()=>state&&render());

function hasDog(address){return !!state.addressNotes?.[addressKey(address)]?.barkingDog;}
function dogWarning(address){return hasDog(address)?'<div class="dog-warning">Barking dog — be prepared before approaching the door.</div>':'';}
function completionNotes(deliveryId){const d=state.deliveries.find(x=>x.id===deliveryId);dialog('Delivery completed',`<p>Delivery time recorded.</p><label for="delivery-notes">General notes (optional)</label><textarea id="delivery-notes" maxlength="4000" placeholder="Anything helpful about this delivery">${esc(d.notes||'')}</textarea><p id="delivery-notes-status" role="status"></p><label class="checkbox-label"><input type="checkbox" id="barking-dog" ${hasDog(d.address)?'checked':''}> Barking dog at this address</label><p class="muted">Remembered on this device for future deliveries.</p><label class="checkbox-label"><input type="checkbox" id="completion-no-text" ${doNotText(state,d.address)?'checked':''}> Do not text this address / unit</label>${d.isCatering?`<button type="button" class="primary" id="share-catering-complete">Share catering photos with Mike</button><p class="muted">Choose Messages and select Mike.${demoMode?' Sample shares are labeled TEST.':''}</p><p data-catering-share-status role="status" aria-live="polite"></p>`:''}<div id="completion-text-wrap"></div>`,null,'Save','Done');const form=$('#modal form'),notes=$('#delivery-notes');let pending=Promise.resolve();const enqueue=fn=>{pending=pending.catch(()=>{}).then(fn);return pending;};const report=e=>{if($('#delivery-notes-status'))$('#delivery-notes-status').textContent=e.message;};const saveNotes=()=>{const value=notes.value;return enqueue(async()=>{if(state.deliveries.find(x=>x.id===deliveryId)?.notes===value.trim()||!value.trim()&&!d.notes)return;await mutate(v=>deliveryNotes(v.deliveries.find(x=>x.id===deliveryId),value));});};notes.onchange=()=>saveNotes().catch(report);const close=async()=>{try{await saveNotes();if(form.isConnected)$('#modal').close();}catch(e){report(e);}};form.querySelector('[data-close]').onclick=close;$('#modal').oncancel=e=>{e.preventDefault();close();};$('#barking-dog').onchange=e=>{const checked=e.target.checked;enqueue(()=>mutate(v=>setAddressPreference(v,d.address,'barkingDog',checked))).catch(report);};const bindText=()=>{const delivery=state.deliveries.find(x=>x.id===deliveryId),skip=doNotText(state,delivery.address);$('#completion-text-wrap').innerHTML=delivery.phone&&!skip?'<button type="button" class="primary" id="completion-text">Prepare customer text</button>':`<p>${skip?'Customer text skipped for this address.':'No customer phone number was entered.'}</p>`;if($('#completion-text'))$('#completion-text').onclick=async()=>{try{await saveNotes();customerMessage(deliveryId,'Delivery completed');}catch(e){report(e);}};};bindText();$('#completion-no-text').onchange=e=>{const checked=e.target.checked;enqueue(()=>mutate(v=>setAddressPreference(v,d.address,'doNotText',checked))).then(bindText).catch(report);};if($('#share-catering-complete'))$('#share-catering-complete').onclick=()=>{saveNotes().catch(report);shareCatering(deliveryId);};}
function showRoute(stops){const google=mapProvider(state.settings)==='google',chunks=[];for(let i=0;i<stops.length;i+=google?4:stops.length)chunks.push(stops.slice(i,i+(google?4:stops.length)));dialog('Your route is ready',`<ol class="route-addresses">${stops.map((d,i)=>`<li><strong>Delivery ${i+1}</strong><div>${esc(navigationAddress(d.address))}</div>${dispatchBadge(d)}${dogWarning(d.address)}<a href="${esc(firstStopURL(d.address))}">Navigate to this stop only</a></li>`).join('')}</ol>${chunks.length>1?'<p class="hint">Google Maps mobile links support four stops per route. Open the next group after finishing the first; every stop remains listed here.</p>':''}${chunks.map((chunk,i)=>`<a class="button-link primary map-launch" href="${esc(directionsURL(chunk.map(d=>d.address),state.settings,navigationAddress))}">Open ${chunks.length>1?'stops '+(i*4+1)+'–'+(i*4+chunk.length):'directions'} in ${providerName(state.settings)}</a>`).join('')}<p class="muted">The route ends at the final delivery. Check locations in Maps before driving.</p>`,null,'Save','Done');}
function tasksView(){const shift=active(),tasks=shift?.tasks||{};return header('Your kitchen tasks.','Check only the work you completed this shift.')+(!shift?'<div class="card">Start a shift to record tasks.</div>':`<form id="tasks-form" class="card">${TASK_GROUPS.map(g=>`<div class="task-group"><label class="checkbox-label"><input type="checkbox" data-task-parent="${g.id}" name="${g.id}" ${tasks[g.id]?'checked':''}> ${g.label}</label>${g.children?`<div data-task-children="${g.id}" class="task-children" ${tasks[g.id]?'':'hidden'}>${g.children.map(c=>`<label class="checkbox-label"><input type="checkbox" name="${g.id}:${c}" ${tasks[`${g.id}:${c}`]?'checked':''}> ${c}</label>`).join('')}</div>`:''}</div>`).join('')}<label for="special-task">Other / special tasks completed</label><textarea id="special-task" name="special" maxlength="1000">${esc(tasks.special||'')}</textarea><button class="primary" type="submit">Save tasks</button><p class="muted">Changes save automatically. Only completed tasks are included in Mike’s report.</p></form>`);}
function bindTasks(){const form=$('#tasks-form');if(!form)return;form.querySelectorAll('[data-task-parent]').forEach(c=>c.onchange=()=>{const children=form.querySelector(`[data-task-children="${c.dataset.taskParent}"]`);if(children){children.hidden=!c.checked;if(!c.checked)children.querySelectorAll('input').forEach(i=>i.checked=false);}});form.onchange=form.onsubmit=async e=>{e.preventDefault();const shiftId=active().id,f=new FormData(form),tasks={special:String(f.get('special')||'').trim()};for(const g of TASK_GROUPS){tasks[g.id]=f.has(g.id);for(const c of g.children||[])tasks[`${g.id}:${c}`]=f.has(g.id)&&f.has(`${g.id}:${c}`);}try{await mutate(v=>{recordTasks(v.shifts.find(s=>s.id===shiftId),tasks,now());});notify('Tasks saved for this shift.');}catch(e){notify(e.message);}};}
const renderBase=render;render=function(){renderBase();bindTasks();};
function checkShiftReminder(){const s=active();if(!s||awaitingReturn(state)||document.hidden||$('#modal').open||busy||!reminderDue(s))return;dialog('Still on shift?',`<p>Delivery cutoff was over 30 minutes ago. If you’ve finished, record your ending mileage and prepare Mike’s report.</p><p>If you’re still working, we’ll remind you in 15 minutes.</p><button type="button" id="reminder-end" class="primary">End shift</button>`,null,'Save','Remind me in 15 minutes');const snooze=()=>mutate(v=>{const x=v.shifts.find(x=>x.id===s.id);if(x)x.reminderAfter=new Date(Date.now()+15*60000).toISOString();}).catch(e=>notify(e.message));$('#modal').querySelector('[data-close]').onclick=async()=>{await snooze();$('#modal').close();};$('#modal').oncancel=()=>{snooze();};$('#reminder-end').onclick=async()=>{await snooze();$('#modal').close();handle('end').catch(e=>notify(e.message));};}
function setupScanner(){const form=$('#modal form');$('#scan-ticket').onclick=()=>openTicketScanner(result=>{if(!form.isConnected)return;for(const [key,selector] of Object.entries({name:'#customer',phone:'#phone',address:'#address',ticket:'#ticket'}))form.querySelector(selector).value=result[key]||'';form.querySelector('#do-not-text').checked=doNotText(state,form.querySelector('#address').value);form.querySelector('#scan-status').textContent='Ticket scanned. Check the name, phone, street number and unit below. Unreadable fields are left blank. Confirm drinks, alcohol and scheduled time before adding.';});}

function notificationSettings(){const n=notificationStatus();return `<section class="card"><h2>Lock-screen reminders</h2><p class="muted">Free reminders at 9:00 p.m. Sunday–Thursday and 9:30 p.m. Friday–Saturday, if your shift is still open. Run reminders arrive 10, 25 and 45 minutes after the last drop-off until you tap End Run. Ending a run or shift cancels its reminder when online. Customer details stay on this device.</p>${demoMode?'<p>Shift and run notifications are disabled in sample mode. Test dispatch can use this installation’s existing notification connection.</p>':`${n.unsupported?`<p>${esc(n.unsupported)}</p>`:''}<p><strong>${n.enabled?'Enabled for this phone':'Not enabled'}</strong>${n.permission==='denied'?' · blocked in phone notification settings':''}</p>${n.pending?'<p class="dog-warning">Reminder update pending. Connect to the internet to finish scheduling or cancellation.</p>':''}${n.error?`<p class="error">${esc(n.error)}</p>`:''}${n.lastTest?`<p class="${n.lastTest.state==='failed'?'error':'hint'}" role="status" aria-live="polite">${esc(n.lastTest.message)}</p>`:''}<div class="actions">${n.enabled?`<button data-action="test-push" class="primary" ${n.lastTest?.state==='sending'?'disabled':''}>${n.lastTest?.state==='sending'?'Sending…':'Send test notification'}</button><button data-action="disable-push">Disable reminders</button>`:`<button data-action="enable-push" class="primary" ${n.unsupported?'disabled':''}>Enable lock-screen reminders</button>`}${n.pending?'<button data-action="retry-push">Retry connection</button>':''}</div><p class="muted">Focus settings and internet availability can delay alerts. Notification setup stays with this installation and isn’t included in backups.</p>`}</section>`;}

function bindReportCharts(){if($('#timeline-shift'))$('#timeline-shift').onchange=e=>{timelineShift=e.target.value;timelinePage=0;render();document.getElementById('report-timeline')?.scrollIntoView({block:'start'});};document.querySelectorAll('[data-timeline-page]').forEach(b=>b.onclick=()=>{timelinePage=Math.max(0,timelinePage+Number(b.dataset.timelinePage));render();document.getElementById('report-timeline')?.scrollIntoView({block:'start'});});document.querySelectorAll('[data-chart-note]').forEach(e=>{const show=()=>{const output=e.closest('.chart-card')?.querySelector('.chart-readout')||$('#chart-selection');if(output){output.textContent=e.dataset.chartNote;output.classList.add('has-value');}};e.onclick=show;e.onfocus=show;e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();show();}};});}

function renderReturnGate(){const run=awaitingReturn(state),shell=$('.app-shell');shell.inert=false;document.body.classList.remove('return-pending');let gate=$('#return-gate');document.body.classList.toggle('has-return-reminder',!!run);if(!run){gate?.remove();return;}if(!gate){gate=document.createElement('section');gate.id='return-gate';gate.className='return-dock';gate.setAttribute('role','region');gate.setAttribute('aria-label','End your run');document.body.append(gate);}gate.innerHTML=`<div><strong>Last delivery completed.</strong><p>End your run once you’re back. You can keep using the app.</p><a class="link" href="${esc(firstStopURL(state.settings.restaurant))}">Directions to restaurant</a></div><button class="primary" id="end-run">End Run</button><p class="return-error" role="alert"></p>`;$('#end-run').onclick=async()=>{const b=$('#end-run');b.disabled=true;try{await handle('return');}catch(e){gate.querySelector('.return-error').textContent=e.message;b.disabled=false;}};}
$('#modal').addEventListener('close',()=>{if(state)renderReturnGate();if(priorityPrompts.length)queuePriorityPrompt();});

function reportPanelSwitch(){return demoMode?`<div class="period-switch report-panels" aria-label="Report section"><button data-action="cost-panel" data-id="charts" class="${reportPanel==='charts'?'primary':''}" aria-pressed="${reportPanel==='charts'}">Shift performance</button><button data-action="cost-panel" data-id="costs" class="${reportPanel==='costs'?'primary':''}" aria-pressed="${reportPanel==='costs'}">Cost comparison</button></div>`:`<div class="hint">Curious about DoorDash / Uber Eats costs? <a href="?demo=1&report=costs">Explore the sample cost comparison →</a></div>`;}
function costReportsView(){return header('The value of your own delivery team.','Explore fees avoided, estimated savings, and evidence of better delivery work.')+reportPanelSwitch()+`<section class="card cost-range"><div class="form-grid"><div><label for="from">From date</label><div class="date-input-wrap"><input id="from" type="date" value="${range.from}"></div></div><div><label for="to">Through date</label><div class="date-input-wrap"><input id="to" type="date" value="${range.to}"></div></div></div><div class="actions"><button data-action="filter">Apply date range</button>${['weekly','monthly','yearly'].map(v=>`<button data-period="${v}" class="${reportView===v?'primary':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></section>`+costLab(state,filtered(),costAssumptions,businessAssumptions);}
function bindCostLab(){const form=$('#cost-form');if(!form)return;const apply=()=>{try{const raw=Object.fromEntries(new FormData(form));raw.ddTablet=!!raw.ddTablet;costAssumptions=validateCostInputs(raw);range=reportDateRange($('#from').value,$('#to').value);render();}catch(e){$('#cost-error').textContent=e.message;}};form.onsubmit=e=>{e.preventDefault();apply();};document.querySelectorAll('[data-cost-preset]').forEach(b=>b.onclick=()=>{const shares={solo:[70,25,5],balanced:[45,40,15],family:[15,35,50]}[b.dataset.costPreset];['soloShare','duoShare','familyShare'].forEach((k,i)=>form.elements[k].value=shares[i]);apply();});$('[data-cost-reset]').onclick=()=>{costAssumptions={...COST_DEFAULTS};businessAssumptions={...BUSINESS_DEFAULTS};render();};}

function bindBusinessLab(){if(!demoMode||!$('#business-form'))return;const update=()=>{range=reportDateRange($('#from').value,$('#to').value);render();};document.querySelectorAll('[data-business-role]').forEach(b=>b.onclick=()=>{businessAssumptions={...businessAssumptions,avoidablePercent:Number(b.dataset.businessRole)};update();});for(const [selector,errorId] of [['#business-form','#business-error'],['#entry-form','#entry-error']])$(selector).onsubmit=e=>{e.preventDefault();try{const raw=Object.fromEntries(new FormData(e.target));if(selector==='#entry-form')raw.entryScenario=!!raw.entryScenario;businessAssumptions=validateBusinessInputs({...businessAssumptions,...raw});update();}catch(err){$(errorId).textContent=err.message;}};}

function manageCustomers(){dialog('Saved customers',`<p class="muted">${state.customers.length} records. Delete removes linked contact details; shift totals stay.</p><button type="button" class="danger" id="manage-delete-all" ${state.customers.length?'':'disabled'}>Delete all saved customers</button>${state.customers.map(c=>`<div class="row"><span>${esc(c.name||'Unnamed customer')}</span><button type="button" class="link" data-manage-delete="${c.id}">Delete customer</button></div>`).join('')}`,null,'Save','Done');$('#manage-delete-all').onclick=()=>handle('delete-all-customers');$('#modal').querySelectorAll('[data-manage-delete]').forEach(b=>b.onclick=()=>handle('delete-customer',b.dataset.manageDelete));}
function groupExistingOrders(selected=[],destinationOnly=false){const shift=active();if(!shift)return;const chosen=new Set(Array.isArray(selected)?selected:[selected]),singles=state.deliveries.filter(d=>d.shiftId===shift.id&&!d.batchId&&['pending','ready'].includes(d.status)),batches=[...new Set(state.deliveries.filter(d=>d.shiftId===shift.id&&d.batchId&&d.status!=='canceled').map(d=>d.batchId))].filter(canAppendBatch);dialog('Select orders for a batch',`<p>${destinationOnly?`${chosen.size} selected orders. Choose their batch.`:'Select one or more existing orders, then choose a batch.'}</p><label for="batch-target">Add selected orders to</label><select id="batch-target" name="target"><option value="new">New batch</option>${batches.map((key,i)=>`<option value="${key}" ${batches.length===1?'selected':''}>${esc(batchName(state,key))} · ${state.deliveries.filter(d=>d.batchId===key&&d.status!=='canceled').length} orders</option>`).join('')}</select>${destinationOnly?'':singles.map(d=>`<label class="checkbox-label"><input type="checkbox" name="orders" value="${d.id}" ${chosen.has(d.id)?'checked':''}> ${esc(d.name||'Delivery')} · ${esc(d.address)}</label>`).join('')||'<p>No pending or ready single orders are available. Active orders stay with their current run.</p>'}`,async f=>{const target=f.get('target')==='new'?id():f.get('target');await mutate(v=>{const ids=destinationOnly?[...chosen]:f.getAll('orders');assignOrders(v,shift.id,ids,target);audit(v,target,'orders grouped',null,ids);});expandedBatches.add(target);selectedOrders.clear();selectingOrders=false;tab='deliveries';render();},'Add selected orders');}
function checkAlcoholReceiptJar(runId){if($('#modal').open||awaitingReturn(state))return;const run=state.runs.find(r=>(!runId||r.id===runId)&&r.needsAlcoholReceiptJar&&!r.alcoholReceiptJarAt&&r.returnedAt);if(!run)return;dialog('Alcohol receipt for Ang',`<p>You’re back at the restaurant. Put the signed alcohol receipt in the jar.</p><label class="checkbox-label"><input name="stored" type="checkbox" required> Signed receipt(s) are in the jar.</label>`,async()=>mutate(v=>{v.runs.find(r=>r.id===run.id).alcoholReceiptJarAt=now();}),'Confirm','Later');}
function exportShiftDetails(shiftId){const shift=state.shifts.find(s=>s.id===shiftId&&s.status==='finalized');if(!shift)throw Error('Choose a completed shift in History.');const rows=detailCSVRows(state,[shift]);download(`delivery-${demoMode?'SAMPLE-':''}shift-${localDate(shift.startedAt)}-${shift.id}-details.csv`,'\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');notify('Delivery details and completed tasks exported for this shift.');}
function cateringPhotosDialog(deliveryId,after){const delivery=()=>state.deliveries.find(d=>d.id===deliveryId);if(!delivery())throw Error('Order not found.');dialog('Catering delivery photos',`<p>After delivery and set-up, take both photos. They are saved only on this device and included in full backups.</p>${['setup','receipt'].map(k=>`<section class="catering-photo"><label for="catering-${k}">${k==='setup'?'Food set-up':'Receipt'} photo</label><div class="actions"><label class="button-link" for="catering-camera-${k}">Take photo<input id="catering-camera-${k}" type="file" accept="image/*" capture="environment" data-catering-input="${k}" hidden></label><label class="button-link" for="catering-${k}">Choose from library<input id="catering-${k}" type="file" accept="image/*" data-catering-input="${k}" hidden></label></div><div data-catering-preview="${k}"></div></section>`).join('')}<p id="catering-save-status" role="status"></p>${delivery().status==='active'?'<button type="button" id="complete-without-photos">Complete delivery without both photos…</button>':''}<button type="button" class="primary" id="share-catering">Share both photos with Mike</button><p class="muted">Choose Messages in the share sheet and select Mike. The browser cannot preselect a recipient while attaching photos.${demoMode?' Sample mode: sharing is available; the accompanying message is labeled TEST.':''}</p><p data-catering-share-status role="status" aria-live="polite"></p><button type="button" id="copy-mike">Copy Mike’s number</button>`,after?async()=>{requireCateringPhotos(delivery());after();}:null,after?'Continue to delivery confirmation':'Save','Done');const draw=()=>{for(const k of ['setup','receipt']){const p=delivery().cateringPhotos?.[k];$(`[data-catering-preview="${k}"]`).innerHTML=p?`<img src="${p.data}" alt="${k==='setup'?'Catering set-up':'Catering receipt'}"><small>Saved on this device</small>`:'<p class="muted">No photo saved. You can take one, choose from your library, or explicitly confirm completion without photos.</p>';}};draw();let saving=false;const photoForm=$('#modal form');$('#modal').querySelectorAll('[data-catering-input]').forEach(input=>input.onchange=async()=>{if(!input.files[0]||saving)return;saving=true;const button=$('#modal [type=submit]');if(button)button.disabled=true;try{const photo=await storedPhoto(input.files[0]);await mutate(v=>{const d=v.deliveries.find(d=>d.id===deliveryId);d.cateringPhotos??={};d.cateringPhotos[input.dataset.cateringInput]=photo;});if(!photoForm.isConnected)return;draw();const shareStatus=photoForm.querySelector('[data-catering-share-status]');if(shareStatus){shareStatus.textContent='';shareStatus.classList.remove('error');}$('#catering-save-status').textContent='Photo saved on this device.';}catch(e){if($('#catering-save-status'))$('#catering-save-status').textContent=e.message;}finally{saving=false;if(button)button.disabled=false;input.value='';}});if($('#complete-without-photos'))$('#complete-without-photos').onclick=()=>confirmDelivery(delivery());$('#share-catering').onclick=()=>shareCatering(deliveryId);$('#copy-mike').onclick=()=>navigator.clipboard.writeText(state.settings.mike).then(()=>notify('Mike’s number copied.')).catch(()=>notify('Mike: '+state.settings.mike));}
async function shareCatering(deliveryId){const modal=$('#modal'),status=modal.querySelector('[data-catering-share-status]'),buttons=[...modal.querySelectorAll('#share-catering,#share-catering-complete')];buttons.forEach(b=>b.disabled=true);try{await shareCateringPhotos(state.deliveries.find(d=>d.id===deliveryId),{sample:demoMode,onStatus:(message,error=false)=>{if(status?.isConnected){status.textContent=message;status.classList.toggle('error',error);}else notify(message);}});}finally{buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}}

function scannerSettings(){const status=cloudScanStatus();return `<section class="card"><h2>In-app ticket scanner</h2><p>${status.enabled?'Connected on this device. New single deliveries and batch stops open the rear camera automatically.':'Tap Scan ticket in an order to connect this device once using the driver setup code. After connection, new single deliveries and batch stops open the camera automatically.'}</p><p class="muted">Cloudflare processes captured ticket photos temporarily, including customer details. No photos or extracted text are stored or logged by our scanner service. The free allowance stops at its limit, with no paid fallback. Saved customer records and downloaded exports remain local. Cloud scanning also uses the allowance in sample mode.</p>${status.enabled?'<button data-action="disable-scanner">Disable cloud scanning</button>':''}</section>`;}

function nearbyOrderHint(delivery){if(!active()||!['pending','ready','active'].includes(delivery.status))return '';const pairs=nearbyPairs(deliveriesFor(active())).filter(p=>p.a===delivery.id||p.b===delivery.id);if(!pairs.length)return '';const names=pairs.map(p=>state.deliveries.find(d=>d.id===(p.a===delivery.id?p.b:p.a))).filter(Boolean).map(d=>d.ticket?'ticket '+d.ticket:d.name||d.address);return `<p class="nearby-note">Nearby: ${names.map(esc).join(', ')} — within about ¼ mile straight-line distance. Consider delivering together.</p>`;}
function nearbySummary(){if(!active())return '';const ds=deliveriesFor(active()),pairs=nearbyPairs(ds);return pairs.length?`<div class="nearby-summary"><strong>${pairs.length} nearby delivery ${pairs.length===1?'pair':'pairs'}</strong><p>Within about ¼ mile in a straight line. Check schedules and the driving route.</p>${pairs.filter(p=>[p.a,p.b].every(id=>{const d=state.deliveries.find(d=>d.id===id);return !d.batchId&&['pending','ready'].includes(d.status);})).map(p=>`<button data-action="nearby-batch" data-id="${p.a},${p.b}">Select these nearby orders</button>`).join('')}</div>`:locationStatus().ready?'':'<p class="muted">Nearby checks need the downloaded Seattle address locations. Manual entry and deliveries remain available.</p>';}
function previewAddress(delivery){if(!delivery)throw Error('Order not found.');dialog('Preview delivery address',`<p>${esc(navigationAddress(delivery.address))}</p><a class="button-link primary map-launch" href="${esc(firstStopURL(delivery.address))}">Open address in ${providerName(state.settings)}</a><p class="muted">Previewing does not mark this order ready or start a run.</p>`,null,'Save','Done');}
function contactCustomer(delivery){if(!delivery?.phone)throw Error('No customer phone number is saved.');phoneURL(delivery.phone);const number=delivery.phone.replace(/[^+0-9]/g,'');dialog('Contact customer',`<p>${esc(delivery.name||'Customer')} · ${esc(delivery.phone)}</p><div class="actions"><a class="button-link primary" href="tel:${esc(number)}">Call customer</a>${doNotText(state,delivery.address)?'<p>This address is marked Do not text. Calling is still available.</p>':`<a class="button-link primary" href="${esc(phoneURL(delivery.phone))}">Open Messages</a>`}</div><p class="muted">For updates or questions before delivery. Nothing is sent automatically, and this does not change order status.</p>`,null,'Save','Done');}
function editDeliveryNotes(delivery){dialog('Delivery notes',`<p>${esc(delivery.name||delivery.address)}</p><label for="edit-delivery-notes">General notes (optional)</label><textarea id="edit-delivery-notes" name="notes" maxlength="4000">${esc(delivery.notes||'')}</textarea>`,async f=>mutate(v=>deliveryNotes(v.deliveries.find(d=>d.id===delivery.id),f.get('notes'))),'Save notes');}
function confirmDelivery(delivery){const d=state.deliveries.find(x=>x.id===delivery.id),missing=d.isCatering&&(!d.cateringPhotos?.setup?.data||!d.cateringPhotos?.receipt?.data);dialog('Do you want to mark this order as delivered?',`<p><strong>${esc(d.name||'This delivery')}</strong></p><p>${esc(d.address)}</p>${d.hasAlcohol?'<div class="alcohol-reminder">Check ID and have the customer sign the alcohol receipt.</div>':''}${missing?'<div class="hint"><strong>Catering photos are incomplete.</strong><p>You can add them from your library now or later. Confirm below to finish without both photos.</p><button type="button" id="add-completion-photos">Add / choose photos</button><label class="checkbox-label"><input type="checkbox" name="photoException" required> I’m sure: mark this catering order delivered without both photos.</label></div>':''}<p>This records delivery time. You can add notes and prepare a customer text next.</p>`,async f=>{await mutate(v=>{const x=v.deliveries.find(x=>x.id===d.id);if(x.status==='delivered')return;if(missing){if(!f.get('photoException'))throw Error('Confirm completion without photos, or add both photos.');confirmPhotoException(x,now());audit(v,x.id,'catering photos waived by driver',null,x.cateringPhotoException);}requireCateringPhotos(x,{allowException:true});audit(v,x.id,'delivered',x.status,'delivered');x.status='delivered';x.completedAt=now();completeRuns(v,x.shiftId,x.completedAt);});expandedCompleted.delete(d.id);if(d.batchId&&state.deliveries.filter(x=>x.batchId===d.batchId&&x.status!=='canceled').every(x=>x.status==='delivered'))expandedBatches.delete(d.batchId);render();completionNotes(d.id);},'Yes — mark delivered');if($('#add-completion-photos'))$('#add-completion-photos').onclick=()=>cateringPhotosDialog(d.id,()=>confirmDelivery(state.deliveries.find(x=>x.id===d.id)));}
function manageCurrentRun(after){const run=currentRun();if(!run)return after?.();const unfinished=state.deliveries.filter(d=>run.deliveryIds.includes(d.id)&&d.status==='active');dialog('End the current run?',`<p>Confirm only once you’re back at the restaurant.</p>${unfinished.length?`<p>${unfinished.length} unfinished ${unfinished.length===1?'order will':'orders will'} return to Ready. They will not be marked delivered or deleted.</p><ul>${unfinished.map(d=>`<li>${esc(d.name||d.address)}</li>`).join('')}</ul>`:'<p>All drop-offs are complete. This records your return.</p>'}<a href="${esc(firstStopURL(state.settings.restaurant))}">Directions to restaurant</a>`,async()=>{let returned;await mutate(v=>{returned=finishRunEarly(v,run.id,now());if(alcoholReturns(v,returned).length)returned.needsAlcoholReceiptJar=true;audit(v,run.id,'run closed by driver',null,{returnedAt:returned.returnedAt,unfinishedDeliveryIds:returned.unfinishedDeliveryIds||[]});});if(returned.needsAlcoholReceiptJar){$('#modal').close();checkAlcoholReceiptJar(returned.id);return;}if(after)await after();},after?'End previous run & continue':'Confirm return / end run');}

function fieldTestControl(shift){if(shift.fieldTestNote)return `<div class="field-test-note">${esc(shift.fieldTestNote)}</div>`;if(demoMode)return '';const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(shift.startedAt));return day==='2026-11-19'?`<button class="compact" data-action="mark-field-test" data-id="${shift.id}">Mark November 19 field-test run data</button>`:'';}

function localRoutingSettings(){return `<section class="card"><h2>Nearby orders & route suggestions</h2><p>${locationStatus().ready?'Address locations are ready on this device.':'Address locations have not finished loading. The first download is about 11 MB; use Wi-Fi if preferred.'}</p>${locationStatus().ready?'':'<button data-action="load-locations">Download / retry address locations</button>'}<p>Seattle public address locations are downloaded once and checked on this device. Your entered addresses are not sent to a geocoding service.</p><p class="muted">Scheduled deliveries lead when due within ten minutes, overdue, or explicitly prioritized. Remaining stops use ticket numbers and nearby groups. Nearby means about ¼ mile straight-line distance. Roads, bridges, traffic and setup time can change the best driving route. Unknown or ambiguous addresses are not guessed.</p><p class="muted">Location data: <a href="https://services.arcgis.com/ZOyb2t4B0UYuYNYH/arcgis/rest/services/TRANSPO_MAFDAP_PV/FeatureServer/0">City of Seattle, Enterprise Data — Addresses (MAF)</a>, November 19, 2026. The City does not warrant accuracy. Check all destinations in Maps.</p></section>`;}

function queuePriorityPrompt(){if(priorityTimer)return;priorityTimer=setTimeout(()=>{priorityTimer=null;if(!priorityPrompts.length)return;if($('#modal').open||busy){queuePriorityPrompt();return;}const key=priorityPrompts.shift(),d=state.deliveries.find(d=>d.id===key);if(!d?.batchId||!d.scheduledAt||d.scheduledPriorityDecided){queuePriorityPrompt();return;}dialog('Should this scheduled delivery take priority?',`<p><strong>${esc(d.name||d.address)}</strong> · ${esc(batchName(state,d.batchId))}</p><p>Scheduled for ${time(d.scheduledAt)}. Move it to the top of the remaining stops?</p><p class="muted">Scheduled orders due within ten minutes, or overdue, automatically take priority even if you choose No now. Maps routes already open must be reopened to reflect changes.</p><div class="actions"><button type="button" id="priority-no">No</button><button type="button" class="primary" id="priority-yes">Yes — move to top</button></div>`,null,'Save','Decide later');const choose=async value=>{try{await mutate(v=>{const x=v.deliveries.find(x=>x.id===key);x.scheduledPriority=value;x.scheduledPriorityDecided=true;audit(v,key,'scheduled priority chosen',null,value);});$('#modal').close();queuePriorityPrompt();}catch(e){$('#modal .error').textContent=e.message;}};$('#priority-yes').onclick=()=>choose(true);$('#priority-no').onclick=()=>choose(false);},120);}
setInterval(()=>{if(!state||busy||$('#modal').open||settingsEditing||document.hidden)return;const before=state.deliveries.filter(d=>d.batchId).map(d=>d.id+':'+d.batchPosition).join('|');applyBatchPriorities(state);const after=state.deliveries.filter(d=>d.batchId).map(d=>d.id+':'+d.batchPosition).join('|');if(before!==after)render();},15000);

function oilSettings(){const oil=state.settings.oil,email=oilEmailStatus();if(!oil)return `<section class="card"><h2>Oil change reminder</h2><p>Track oil changes every 5,000 miles, with a 500-mile warning and a due reminder.</p><button class="primary" data-action="oil-setup">Set up oil reminders</button><p class="muted">Uses odometer readings you enter; the app cannot detect miles driven between entries.</p></section>`;const mileage=oilMileage(state),status=oilStatus(oil,mileage);return `<section class="card oil-settings"><div class="row"><h2>Oil change</h2><button data-action="oil-setup">Edit</button></div><dl class="essentials"><dt>Last oil change</dt><dd>${oil.lastChangedMileage.toLocaleString()} miles</dd><dt>Next oil change</dt><dd>${oil.dueMileage.toLocaleString()} miles</dd><dt>Latest recorded odometer</dt><dd>${mileage.toLocaleString()} miles</dd></dl><p class="${status.stage==='ok'?'muted':'oil-warning'}">${status.stage==='due'?'Time to change your oil.':status.stage==='soon'?`Within 500 miles — ${Math.max(0,status.remaining).toLocaleString()} miles to go.`:`${status.remaining.toLocaleString()} miles until your next oil change.`}</p><div class="actions"><button class="primary" data-action="oil-change">I changed my oil</button><button data-action="oil-mileage">Update current odometer</button></div><h3>Email reminders</h3>${demoMode?'<p>Emails are disabled in sample mode. Mileage and oil changes here are fictional.</p>':`<p>${oil.emailEnabled?'Enabled on this installation':'Not enabled'}${email.recipient?' · '+esc(email.recipient):''}</p><p class="muted">${email.checked&&!email.configured?'Email sender setup is still required. Local tracking works now.':'Two reminders per oil-change cycle: within 500 miles and when due. Only your oil settings and latest recorded mileage are sent to the reminder service.'}</p>${email.error?`<p class="error">${esc(email.error)}</p>`:''}<div class="actions"><button data-action="oil-check">Check email setup</button>${oil.emailEnabled?'<button data-action="oil-disable">Disable oil emails</button>':'<button data-action="oil-enable">Enable oil emails</button>'}</div>`}<p class="muted">After a change, the next target is the actual change mileage + 5,000. Record personal driving here if you need an earlier reminder.</p></section>`;}
async function setupOil(){let initial=state.settings.oil;if(!initial&&!demoMode){try{const status=await checkOilEmail();if(status.initial)initial=status.initial;}catch{}}if(!initial&&demoMode)initial={lastChangedMileage:65000,dueMileage:70000};dialog('Oil reminder settings',`<label for="oil-last">Mileage at last oil change</label><input id="oil-last" name="last" type="number" inputmode="decimal" min="0" step="0.1" required value="${initial?.lastChangedMileage??''}"><label for="oil-due">Next oil change due at</label><input id="oil-due" name="due" type="number" inputmode="decimal" min="0" step="0.1" required value="${initial?.dueMileage??''}"><p class="muted">Future changes use a 5,000-mile interval. Saving a corrected schedule resets its reminder cycle; it does not send an email unless email reminders are enabled.</p>`,async f=>{await mutate(v=>{updateOilSchedule(v,f.get('last'),f.get('due'));});},'Save oil settings');}
function changeOil(){const oil=state.settings.oil;dialog('Record an oil change',`<p>Enter the odometer mileage when the oil was changed. The next target will be 5,000 miles later and both reminders will reset.</p><label for="oil-changed">Oil changed at mileage</label><input id="oil-changed" name="mileage" type="number" inputmode="decimal" min="${oil.lastChangedMileage}" step="0.1" required value="${oilMileage(state)}">`,async f=>{await mutate(v=>recordOilChange(v,f.get('mileage')));notify('Oil change saved. Next reminder cycle reset.');},'Save oil change');}
function updateOilMileage(){dialog('Update vehicle odometer',`<label for="oil-current">Current odometer mileage</label><input id="oil-current" name="mileage" type="number" inputmode="decimal" min="${state.settings.oil.lastChangedMileage}" step="0.1" required value="${oilMileage(state)}"><p class="muted">Use this for miles driven outside your delivery shifts. Shift readings are also checked automatically.</p>`,async f=>mutate(v=>recordOilMileage(v,f.get('mileage'))),'Save odometer');}
async function enableOilEmails(){if(demoMode)return;let service;try{service=await checkOilEmail();}catch(e){return dialog('Oil email setup',`<p>${esc(e.message)}</p><p>Local oil tracking still works.</p>`,null,'Save','Done');}if(!service.configured)return dialog('Email sender setup needed',`<p>The oil tracker is ready, but automatic email sending has not been connected yet.</p><p>No emails will be sent until a free sender is configured and verified. Your saved mileage remains available here.</p>`,null,'Save','Done');dialog('Enable oil-change emails?',`<p>Send the 500-mile and due reminders to <strong>${esc(service.recipient)}</strong>.</p><p>Only oil settings and the latest recorded odometer are synced. No customer data, reports, or reimbursement values are included.</p>`,async()=>{await mutate(v=>v.settings.oil.emailEnabled=true);try{await syncOilEmail(state,{force:true});notify('Oil reminder emails enabled.');}catch(e){notify(e.message);}render();},'Enable email reminders');}

function tipMoney(cents){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);}
function preparationTimer(d){if(!['pending','ready'].includes(d.status))return '';return `<p class="preparation-timer" data-prep-timer="${esc(d.id)}"></p>${delayDue(d)?`<button class="outline" data-action="delay-text" data-id="${d.id}">Review preparation delay</button>`:''}`;}
function updatePreparationTimers(){for(const node of document.querySelectorAll('[data-prep-timer]')){const d=state.deliveries.find(x=>x.id===node.dataset.prepTimer);if(!d)continue;node.textContent=d.readySource==='manager-dispatch'?`Ready from Mike · waiting ${elapsedLabel(Math.max(0,Math.floor((Date.now()-Date.parse(d.readyAt))/1000)))}`:`${d.readyAt?'Preparation time':'Preparing'} · ${elapsedLabel(elapsedSeconds(d))}${d.readyAt?' · Ready for '+elapsedLabel(Math.max(0,Math.floor((Date.now()-Date.parse(d.readyAt))/1000))):''}`;}}
function preparationDelay(deliveryId){const d=state.deliveries.find(x=>x.id===deliveryId);if(!d||!delayDue(d))return;const noText=doNotText(state,d.address);dialog('Order taking a little longer?',`<p><strong>${esc(d.name||'Delivery')}</strong><br>${esc(d.address)}</p><p>This order was added at least 20 minutes ago and delivery hasn’t started.${d.status==='ready'?' It is marked ready.':''}${d.scheduledAt?' This is a scheduled delivery; check its requested time before sending.':''}</p>${noText?'<p class="hint">This address is marked Do not text. No message will be prepared.</p>':!d.phone?'<p class="hint">No phone number is saved. Edit the order if you need to contact the customer.</p>':`<label for="delay-message">Message to customer</label><textarea id="delay-message" name="message" rows="5" required>${esc(DELAY_MESSAGE)}</textarea><p class="muted">You review and send this in Messages. The app cannot confirm whether a text was sent.</p>`}`,async f=>{const text=String(f.get('message')||'').trim();if(!noText&&d.phone&&!demoMode)phoneURL(d.phone);await mutate(v=>{const order=v.deliveries.find(x=>x.id===deliveryId);if(order)order.preparationDelayReviewedAt=now();});if(!noText&&d.phone&&!demoMode)compose(d.phone,text,'Preparation delay message');else if(demoMode&&!noText&&d.phone)notify('Sample mode: delay reviewed; no message opened.');},!noText&&d.phone?'Prepare text':'Dismiss','Not now');}
function checkPreparationDelay(){if(!state||busy||document.hidden||$('#modal').open||document.querySelector('.scanner-dialog[open]'))return;const shift=active();if(!shift)return;const d=state.deliveries.find(x=>x.shiftId===shift.id&&delayDue(x)&&!delayShown.has(x.id));if(d){delayShown.add(d.id);preparationDelay(d.id);}}
const delayShown=new Set();
setInterval(()=>{if(!state||document.hidden)return;updatePreparationTimers();checkPreparationDelay();},1000);
function tipCalculator(shiftId){const shift=state.shifts.find(x=>x.id===shiftId);if(!shift)throw Error('Start a shift before calculating tips.');const saved=shift.tips;let calculator=newTipCalculator(saved?(saved.totalCents/100).toFixed(2):'0');calculator.trail=saved?.calculation||'';dialog('Tip calculator',`<p class="muted">Tap each tip, then +. When you’re finished, calculate your tip-out.</p><section class="tip-calculator" aria-label="Tip calculator keypad"><div class="calculator-screen"><div id="calculator-trail" class="calculator-trail"></div><output id="calculator-display" aria-label="Calculator display">0</output><span class="calculator-currency">DOLLARS</span></div><div class="calculator-keys">${[['AC','Clear calculator'],['back','Backspace'],['÷','Divide'],['×','Multiply'],['7','7'],['8','8'],['9','9'],['−','Subtract'],['4','4'],['5','5'],['6','6'],['+','Add'],['1','1'],['2','2'],['3','3'],['=','Equals'],['0','0'],['.','Decimal point']].map(([key,label])=>`<button type="button" data-calculator-key="${key}" aria-label="${label}" class="${['+','−','×','÷','='].includes(key)?'calculator-operator':''} ${key==='0'?'calculator-zero':''}">${key==='back'?'⌫':key}</button>`).join('')}</div></section><div class="calculator-servers"><span>Servers sharing 15%</span><div><button type="button" id="fewer-servers" aria-label="One fewer server">−</button><input id="tip-servers" aria-label="Number of servers" name="servers" type="number" inputmode="numeric" min="1" max="100" step="1" required value="${saved?.serverCount||1}"><button type="button" id="more-servers" aria-label="One more server">+</button></div></div><p class="muted calculator-private">70% you · 15% servers · 15% kitchen. Saved privately with this shift and its exports.</p>`,async f=>{const resultState=tipCalculatorKey(calculator,'='),result=calculateTips([{ticket:'Calculator total',amount:resultState.display}],Number(f.get('servers')));await mutate(v=>{v.shifts.find(x=>x.id===shiftId).tips={...result,calculation:resultState.trail,updatedAt:now()};});dialog('Your tip-out',`<p class="muted">Saved with this shift · ${result.serverCount} server${result.serverCount===1?'':'s'}</p><div class="tip-out-total"><span>Total tips</span><strong>${tipMoney(result.totalCents)}</strong></div><dl class="tip-out-breakdown"><div class="driver-tip"><dt>Your 70%</dt><dd>${tipMoney(result.driverCents)}</dd></div><div><dt>Servers’ 15%</dt><dd>${tipMoney(result.serversCents)}</dd></div><div><dt>Each server</dt><dd>${[...new Set(result.serverShares)].map(tipMoney).join(' / ')}</dd></div><div><dt>Kitchen’s 15%</dt><dd>${tipMoney(result.kitchenCents)}</dd></div></dl><p class="muted">Rounding pennies are included in the split. Tips stay out of Mike’s text report.</p><button type="button" id="edit-tip-calculation">Edit calculation</button>`,null,'Save','Done');$('#edit-tip-calculation').onclick=()=>tipCalculator(shiftId);},'Calculate tip-out');const draw=()=>{$('#calculator-display').textContent=calculator.display;$('#calculator-trail').textContent=calculator.trail||'Add your ticket tips';};const press=key=>{try{calculator=tipCalculatorKey(calculator,key);$('#modal .error').textContent='';draw();}catch(e){$('#modal .error').textContent=e.message;}};$('#modal').querySelectorAll('[data-calculator-key]').forEach(b=>b.onclick=()=>press(b.dataset.calculatorKey));$('#fewer-servers').onclick=()=>{$('#tip-servers').value=Math.max(1,(Number($('#tip-servers').value)||1)-1);};$('#more-servers').onclick=()=>{$('#tip-servers').value=Math.min(100,(Number($('#tip-servers').value)||1)+1);};const form=$('#modal form');form.onkeydown=e=>{if(e.target.matches('input,textarea'))return;const map={'-':'−','*':'×','/':'÷','Enter':'=','Backspace':'back','Escape':'AC'};const key=map[e.key]||e.key;if(/^[0-9.]$/.test(key)||['+','−','×','÷','=','back','AC'].includes(key)){e.preventDefault();press(key);}};draw();}

function dispatchMode(){return demoMode?'test':'live';}
function dispatchBadge(d){return d.dispatchId?`<span class="badge dispatch-label dispatch-${esc(d.dispatchColor)}">From Mike · Addition ${d.dispatchAddition}</span>`:'';}
function dispatchSettings(){const c=dispatchConfig(dispatchMode());return `<section class="card"><h2>Mike’s dispatch</h2><p>${demoMode?'Test pairing: fictional orders go only to sample records.':'Live pairing: Mike’s additions arrive ready in your active shift.'}</p><p class="muted">One addition uses one color: orange, blue, purple, yellow. The sequence restarts at orange when no unfinished Mike additions remain, and at each new shift. Uncollected orders expire after 24 hours. Names and numbers are encrypted before transfer; dispatch alerts contain no customer details.</p>${c?.connected?'<p>Manager paired on this installation. Pair once; it stays connected across shifts.</p>':'<p>No manager is paired here.</p>'}<div class="actions"><button class="primary" data-action="dispatch-pair">${c?.connected?'Show pairing code':'Pair manager device'}</button>${c?.connected?'<button data-action="dispatch-check">Check for additions</button><button data-action="dispatch-push">Connect dispatch notifications</button><button data-action="dispatch-disconnect">Disconnect manager</button>':''}</div><p id="dispatch-status" class="muted">${esc(dispatchMessage)}</p><a class="button-link" href="manager.html" target="_blank" rel="noopener">Open manager screen</a><p class="muted">Test first on the Mac manager screen and iPhone sample mode. Pairing codes are private: anyone with a code can add orders until you disconnect them. Keep this phone’s backup current; pairing keys stay on the installation and are not included in backups.</p></section>`;}
async function pairManager(){if(!cloudScanStatus().enabled&&!notificationStatus().enabled)return dialog('Connect dispatch on this device', '<p>Enter the driver setup code once. This connects the encrypted dispatch service without requesting camera or notification permission.</p><label for="dispatch-setup">Driver setup code</label><input id="dispatch-setup" name="code" type="password" autocomplete="off" required>',async f=>{await enableCloudScan(f.get('code'));await pairManager();},'Connect');const c=await createDispatchPair(dispatchMode());dialog('Pair Mike’s manager screen',`<p>${demoMode?'TEST':'LIVE'} pairing. Paste this private code into the manager screen on Mike’s phone or your Mac. It permits order additions and batch requests for unstarted Mike orders on this installation.</p><label for="dispatch-code">Private pairing code</label><textarea id="dispatch-code" readonly rows="4" spellcheck="false">${esc(pairingCode(c))}</textarea><button type="button" id="copy-dispatch-code">Copy pairing code</button><p class="muted">${demoMode?'Sample records only.':'Real shift records.'} Orders wait if no shift is active. Notifications use this installation’s existing lock-screen connection; connect it in Settings if needed.</p>`,null,'Save','Done');$('#copy-dispatch-code').onclick=async()=>{try{await navigator.clipboard.writeText($('#dispatch-code').value);$('#copy-dispatch-code').textContent='Copied';}catch{$('#dispatch-code').select();}};}
async function receiveDispatch(manual=false){const c=dispatchConfig(dispatchMode());if(!c?.connected){if(manual)notify('Pair a manager first.');return;}if(dispatchBusy||busy||document.hidden)return;dispatchBusy=true;try{const response=await dispatchCall('inbox',{},c.driverToken);dispatchMessage=response.packets.length?`${response.packets.length} addition(s) waiting.`:'Connected · no additions waiting.';for(const packet of response.packets){if($('#modal').open||document.querySelector('.scanner-dialog[open]')||settingsEditing||busy)break;const payload=await openDispatch(c,packet);packet.pairId=c.id;if(['group','reorder'].includes(payload.action))packet.allowedDispatchIds=(await dispatchCall('status',{},c.driverToken)).packets.map(x=>x.id);if($('#modal').open||busy)break;busy=true;let result;try{state=await updateStored(v=>{result=applyDispatch(v,packet,payload,dispatchMode());applyBatchPriorities(v);completeRuns(v);});}finally{busy=false;}if(result.waiting){dispatchMessage='New orders are waiting. Start a shift to receive them automatically.';if(manual)notify(dispatchMessage);break;}await dispatchCall('ack',{id:packet.id},c.driverToken);dispatchMessage=result.rejected?result.rejected:result.reordered?'Mike’s route order received and applied.':result.grouped?'Mike’s batch request received and applied.':result.added?`Addition ${result.addition} received and saved.`:'Already saved · receipt confirmed.';if(result.rejected)notify(result.rejected);if(result.reordered){render();notify('Mike’s route order applied. Scheduled priorities remain in effect.');}if(result.grouped){render();notify('Mike’s batch request applied.');}if(result.added){render();notify(`From Mike: ${result.added} order${result.added===1?'':'s'} added · Addition ${result.addition}.`);}}await syncDispatchView(c);if(manual)notify(dispatchMessage);}catch(e){dispatchMessage=e.message;if(manual)notify(e.message);}finally{dispatchBusy=false;const output=$('#dispatch-status');if(output)output.textContent=dispatchMessage;}}
setInterval(()=>{if(state)receiveDispatch();},8000);
addEventListener('online',()=>{if(state)receiveDispatch();});document.addEventListener('visibilitychange',()=>{if(state&&!document.hidden)receiveDispatch();});navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='open-dispatch'){const requested=e.data.mode==='test';if(requested!==demoMode){location.href=requested?'?demo=1&notification=dispatch':'?notification=dispatch';return;}receiveDispatch(true);}});

setTimeout(()=>{if(state)receiveDispatch();},0);

let dispatchViewSignature='',dispatchViewAt=0;
async function syncDispatchView(c){const status=await dispatchCall('status',{},c.driverToken),view=dispatchSnapshot(await read(),status.packets.map(x=>x.id)),signature=c.id+JSON.stringify({...view,updatedAt:''});if(signature===dispatchViewSignature&&Date.now()-dispatchViewAt<300000)return;const revision=Math.max(Date.now(),Number(localStorage.getItem('dm-dispatch-view-revision-'+c.id)||0)+1);localStorage.setItem('dm-dispatch-view-revision-'+c.id,String(revision));await dispatchCall('view',await sealDispatchView(c,view,revision),c.driverToken);dispatchViewSignature=signature;dispatchViewAt=Date.now();}

function commandIcon(name){const paths={arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16"/>',contact:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3v-7a8 8 0 1 1 18-4Z"/><path d="M8 10h8m-8 4h5"/>',edit:'<path d="m4 16-1 5 5-1L20 8l-4-4L4 16Zm10-10 4 4"/>',batch:'<rect x="3" y="5" width="12" height="15" rx="2"/><path d="M8 2h11a2 2 0 0 1 2 2v12M6 10h6m-6 4h6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',check:'<path d="m5 12 4 4L20 5"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3V7Z"/><circle cx="12" cy="13" r="4"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.more}</svg>`;}
function deliveryActions(d,{pending,ready,done,batchWaiting}){const primary=pending?['ready','Mark ready','check',d.id]:ready?['route',d.batchId?'Start batch':'Start delivery','arrow',d.batchId||d.id]:!done?['delivered','Delivered','check',d.id]:null;return `<div class="delivery-command">${d.isCatering?`<button class="delivery-photo-action" data-action="catering-photos" data-id="${d.id}">${commandIcon('camera')}<span>Catering photos</span><small>${['setup','receipt'].filter(k=>d.cateringPhotos?.[k]).length}/2 added</small></button>`:''}${primary?`<button class="delivery-next" data-action="${primary[0]}" data-id="${primary[3]}" ${ready&&batchWaiting?'disabled title="Mark all batch stops ready first"':''}><span>${primary[1]}</span><span class="next-action-icon">${commandIcon(primary[2])}</span></button>`:''}<div class="delivery-quick-row"><button data-action="${d.status==='active'?'navigate':'preview-address'}" data-id="${d.id}">${commandIcon('map')}<span>${d.status==='active'?'Navigate':'Preview map'}</span></button>${d.phone?`<button data-action="contact-customer" data-id="${d.id}">${commandIcon('contact')}<span>Text / call</span></button>`:''}</div><div class="delivery-tools-row"><button data-action="edit-address" data-id="${d.id}">${commandIcon('edit')}<span>Edit address</span></button>${!d.batchId&&(pending||ready)?`<button data-action="group-order" data-id="${d.id}">${commandIcon('batch')}<span>Add to batch</span></button>`:done?`<button data-action="delivery-notes" data-id="${d.id}">${commandIcon('edit')}<span>Edit notes</span></button>`:'<span></span>'}${pending||ready||done||d.batchId?`<button class="delivery-more" aria-haspopup="dialog" data-action="order-tools" data-id="${d.id}" aria-label="More order tools for ${esc(d.name||d.address)}">${commandIcon('more')}<span>More</span></button>`:'<span></span>'}</div></div>`;}
function orderTools(deliveryId){const d=state.deliveries.find(x=>x.id===deliveryId);if(!d)return;const items=[];if(d.status==='ready')items.push(['pending','Still preparing','Move this order back to preparation.']);if(['pending','ready'].includes(d.status))items.push(['edit','Edit order','Customer, ticket, schedule and order details.']);if(d.batchId&&d.status!=='delivered')items.push(['ungroup-order','Remove from batch','Keep the order as a single delivery.']);if(d.status==='delivered')items.push(['undo','Undo delivered','Mark this order as not delivered.']);if(['pending','ready'].includes(d.status))items.push(['cancel','Remove order','Remove this order from the current shift.']);if(!items.length)items.push(['edit-address','Edit address','Correct the destination without changing delivery status.']);dialog('Order tools',`<p class="muted">${esc(d.name||'Delivery')} · ${esc(d.address)}</p><div class="order-tools-menu">${items.map(([action,label,description])=>`<button type="button" data-tool-action="${action}" class="${action==='cancel'?'danger':''}"><strong>${label}</strong><small>${description}</small></button>`).join('')}</div>`,null,'Save','Done');$('#modal').querySelectorAll('[data-tool-action]').forEach(b=>b.onclick=async()=>{$('#modal').close();try{await handle(b.dataset.toolAction,deliveryId);}catch(e){notify(e.message);}});}

// Appearance belongs to this installation, independently of shift records and backups.
function appearancePreference(){try{const value=localStorage.getItem('dm-appearance');return ['light','dark'].includes(value)?value:'system';}catch{return 'system';}}
function applyAppearance(){const mode=appearancePreference(),dark=mode==='dark'||(mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#101c18':'#173e36');}
function appearanceSettings(){const mode=appearancePreference();return `<section class="card appearance-card"><h2>Appearance</h2><p class="muted">Choose what feels comfortable on the road.</p><div class="appearance-options" role="group" aria-label="App appearance">${[['system','◐','Use device setting'],['light','☀','Light'],['dark','☾','Dark']].map(([value,icon,label])=>`<button type="button" data-appearance="${value}" aria-pressed="${mode===value}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div><p class="muted">Use device setting follows your phone’s light or dark appearance. Saved on this device.</p></section>`;}
document.addEventListener('click',event=>{const button=event.target.closest('[data-appearance]');if(!button)return;try{localStorage.setItem('dm-appearance',button.dataset.appearance);applyAppearance();document.querySelectorAll('[data-appearance]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}catch{notify('Could not save appearance. Please allow storage for this app.');}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyAppearance);
applyAppearance();
